INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91635, 'spa', 'Aplastar, quebrantar (activo)', 'Aplastar, quebrantar (activo): sentido activo del Piel, aplastar, hacer pedazos o pisotear. Dios aplasta a Rahab-Egipto (Sal 89:10) y los malvados aplastan al pueblo de Dios (Sal 94:5). En Isa 53:10, el Señor quiso quebrantarlo. Proverbios 22:22 advierte contra aplastar al afligido en la puerta. El agente activo es típicamente Dios en juicio u opresores humanos contra los vulnerables.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91641, 'spa', 'Ser humillado, abatido', 'Ser humillado, abatido: extensión figurada que significa ser humillado o abatido, distinta de la destrucción física. En Jer 44:10, el pueblo no ha sido humillado ni se ha arrepentido hasta el día de hoy. El énfasis recae sobre la disposición interior más que sobre la fuerza externa: una falta de respuesta apropiada al llamado de Dios al arrepentimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91649, 'spa', 'Los contritos, los quebrantados', 'Los contritos, los quebrantados: participio Nifal sustantivado נִדְכָּאִים en Isa 57:15: ''los quebrantados'' o ''los contritos'' con quienes Dios escoge habitar. Este es uno de los usos derivados más importantes de la raíz: el quebrantamiento se convierte en una cualificación espiritual para la cercanía divina, transformando lo que en otros contextos es pura destrucción en una marca paradójica de gracia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91652, 'spa', 'Aplastar, ser aplastado', 'Aplastar o ser aplastado, describiendo violencia física, opresión o sufrimiento intenso. Cinco ocurrencias abarcan desde el aplastamiento hostil del débil por los malvados (Sal 10:10), el quebrantamiento divino en juicio o prueba (Sal 44:19; 51:8), hasta la experiencia del salmista destrozado por la aflicción (Sal 38:8). El español emplea «aplastado» y «nos aplastaste», transmitiendo una fuerza aplastante y abrumadora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91657, 'spa', 'Contrito, quebrantado espiritualmente', 'Contrito o quebrantado de espíritu: el sentido espiritualmente positivo de un corazón humillado y abierto ante Dios. En el Salmo 51:17, el participio Nifal nidkeh describe un corazón que Dios valora por encima de todos los sacrificios: «al corazón contrito y humillado no despreciarás tú, oh Dios». El español pasa del violento «aplastado» al reverente «contrito», marcando la transformación teológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91660, 'spa', 'Demostrativo arameo', 'Pronombre demostrativo arameo que significa «este» o «aquel mismo», con tres apariciones en las visiones de Daniel. Daniel 2:31 señala «esta imagen» (צַלְמָא דִכֵּן) en el sueño de Nabucodonosor. Daniel 7:20-21 refiere «aquel cuerno» (קַרְנָא דִכֵּן) en la visión de la cuarta bestia, el cuerno notable que guerreaba contra los santos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91661, 'spa', 'Carneros sacrificiales', 'Sustantivo arameo para carneros (machos de ovejas), que aparece tres veces en Esdras en contextos de sacrificio en el templo. Esdras 6:9 lista carneros (דִּכְרִין) entre los animales necesarios para las ofrendas. Esdras 6:17 los enumera en el sacrificio de dedicación. Esdras 7:17 los incluye en la lista de compras de Esdras para las ofrendas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91664, 'spa', 'pobre, necesitado (socioeconómico) — Persona de bajo estatus socioeconómico, car', 'pobre, necesitado (socioeconómico) — Persona de bajo estatus socioeconómico, carente de recursos materiales. Es el sentido predominante, empleado como adjetivo y sustantivo para designar a los pobres como clase social. La Torá exige justicia para el דַּל (Éx 23:3; Lv 19:15), y las normas de ofrenda proveen alternativas para quienes no pueden costear el sacrificio estándar (Lv 14:21). Proverbios lo contrasta con el עָשִׁיר (rico) repetidamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91666, 'spa', 'débil, endeble, sin poder — Débil, endeble o carente de poder o influencia, más ', 'débil, endeble, sin poder — Débil, endeble o carente de poder o influencia, más que específicamente empobrecido. Gedeón protesta que su clan es el más débil (דַּל) en Manasés (Jue 6:15), la casa de Saúl se debilita cada vez más (2 S 3:1), y el salmista alaba el cuidado por el débil y necesitado (Sal 41:1; 72:13; 82:3-4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91676, 'spa', 'humilde, bajo — Humilde o bajo de espíritu, denotando sumisión mansa más que pri', 'humilde, bajo — Humilde o bajo de espíritu, denotando sumisión mansa más que privación material. En Sofonías 3:12, Dios promete dejar en medio de Israel un pueblo afligido y humilde (עָנִי וָדָל) que se refugia en el Señor. Apunta a una cualidad espiritual más que a una condición social o física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91678, 'spa', 'delgado, demacrado — Delgado, demacrado o físicamente emaciado, describiendo el ', 'delgado, demacrado — Delgado, demacrado o físicamente emaciado, describiendo el desgaste corporal. En Génesis 41:19 describe las siete vacas flacas y feas del faraón que devoran a las gordas, y en 2 Samuel 13:4 describe el visible deterioro físico de Amnón. Refleja la delgadez visible y el declive físico, no la pobreza ni la debilidad social.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91681, 'spa', 'Saltar, brincar', 'Saltar, brincar o pasar por encima de un obstáculo, describiendo un movimiento físico vigoroso. El Piel intensifica la acción. En el Salmo 18:29 (= 2 S 22:30), el salmista salta una muralla por poder divino. En Cantares 2:8, el amado viene «saltando sobre los montes», evocando un acercamiento apasionado. Isaías 35:6 emplea el símil del ciervo para la restauración mesiánica. Sofonías 1:9 aplica el verbo al acto ritual de traspasar un umbral pagano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91682, 'spa', 'Sacar, extraer', 'Sacar agua de un pozo o cisterna y, por extensión, extraer o levantar algo de un lugar profundo. El sentido literal aparece en Éxodo 2:16, 19, donde las hijas de Reuel sacan agua. Proverbios 20:5 aplica la imagen figuradamente: una persona perspicaz saca el consejo profundo del corazón. El Salmo 30:1 lo emplea para la liberación divina, con Dios sacando al salmista de la hondura mortal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91684, 'spa', 'Pobres, clase desposeída', 'Los más pobres, la clase desposeída: sustantivo femenino colectivo que designa el estrato económico más bajo de una población. Las cinco ocurrencias describen a los que quedaron en Judá tras la deportación: los pobres de la tierra que los babilonios no se molestaron en exiliar (2 R 24:14; 25:12; Jer 40:7; 52:15-16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91688, 'spa', 'Débil, endeble', 'Débil o endeble en sentido físico o cualitativo más que económico. En Génesis 41:19, el faraón describe las siete vacas feas y flacas de su sueño, y este vocablo capta su debilidad demacrada. El francés «faible» se aparta del significado de pobreza hacia la debilidad física, distinguiendo este uso del sentido de clase social.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91689, 'spa', 'Enturbiar aguas', 'Enturbiar, agitar o enlodar — específicamente referido al agua ensuciada al pisotear con los pies. Ezequiel 32:2 usa la forma consecutiva «y enturbiaste» (וַתִּדְלַח) con las aguas como complemento. Ezequiel 32:13 emplea el imperfecto dos veces: «las enturbiarán» (תִּדְלְחֵם), aunque algunos estudiosos enmiendan la segunda aparición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91691, 'spa', 'Delaías (nombre propio)', 'Delaías o Delayahu, nombre personal teofórico que significa ''Yahvé ha sacado/librado,'' llevado por cinco individuos distintos en la Biblia hebrea: (a) un sacerdote al frente del turno vigésimo tercero bajo David (1 Cr 24:18); (b) un príncipe en la corte de Joacim que intercedió contra la quema del rollo de Jeremías (Jer 36:12, 25); (c) un descendiente de Zorobabel en la línea davídica (1 Cr 3:24); (d) el cabeza de una familia sin genealogía comprobable tras el exilio (Esd 2:60).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91695, 'spa', 'Dalila', 'Nombre personal de la mujer filistea (o asociada a los filisteos) que sedujo a Sansón para que revelara la fuente de su fuerza extraordinaria. Las traducciones son notablemente consistentes entre idiomas — español «Dalila», francés «Dalila», alemán «Delila» — con ligeras adaptaciones fonológicas. Las seis atestiguaciones se encuentran en la narrativa concentrada de Jueces 16:4-18.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91696, 'spa', 'Ramas, ramos', 'Ramas o ramos de un árbol, siempre en plural y siempre en contextos profético-metafóricos que representan naciones como árboles. El español rinde uniformemente ''ramas/sus ramas'', el francés usa ''branche'' y el alemán ''Zweig/seine Zweige'', confirmando el sentido botánico constante. El sufijo posesivo (-av, ''sus'') aparece en la mayoría de las apariciones, reforzando la imagen de ramas que pertenecen a un árbol que simboliza una nación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91699, 'spa', 'Ser abatido, humillado', 'Ser abatido, humillado, reducido a un estado de debilidad o postración, generalmente de personas en angustia ante Dios. Salmo 116:6 es paradigmático: ''Fui abatido y él me salvó.'' Jueces 6:6 describe el abatimiento colectivo de Israel bajo la opresión madianita, mientras que Salmos 79:8 y 142:6 expresan el clamor comunitario de un pueblo profundamente debilitado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91703, 'spa', 'Colgar, pender', 'Colgar, pender, caer flojo: el sentido más físico y probablemente original de la raíz. Job 28:4 retrata a mineros suspendidos de cuerdas, balanceándose lejos de todo camino humano, mientras Proverbios 26:7 compara las piernas del cojo que ''cuelgan inertes'' con un proverbio en boca del necio. El árabe tadaldala (''balancearse, colgar'') confirma este significado espacial concreto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91704, 'spa', 'Disminuir, empobrecer', 'Disminuir, declinar, adelgazarse o empobrecerse, dicho de naciones, aguas o vitalidad física que se desvanecen. Isaías 19:6 lo aplica a los ríos de Egipto que se secan, Isaías 17:4 a la gloria de Jacob que mengua, e Isaías 38:14 a los ojos desfallecientes de Ezequías. El hebreo proyecta imágenes concretas sobre realidades geopolíticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91709, 'spa', 'Gotear o filtrar', 'Gotear, destilar o filtrar, con tres apariciones en la literatura sapiencial. Job 16:20 y Salmo 119:28 usan el perfecto דָּלְפָה con sentido de llanto: «mi ojo gotea hacia Dios» y «mi alma se deshace de tristeza» — lágrimas que fluyen o vida que se agota. Eclesiastés 10:18 emplea el imperfecto יִדְלֹף: «gotea la casa» por la negligencia en mantener el techo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91712, 'spa', 'Arder, encender', 'Arder, encender o inflamarse, tanto fuego literal como ardor metafórico. Abdías 1:18 describe a la casa de José ardiendo entre Edom, y Ezequiel 24:10 ordena ''enciende el fuego'' en la alegoría del juicio. Isaías 5:11 habla del vino que ''inflama'', y Proverbios 26:23 empareja ''labios ardientes'' con un corazón perverso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91713, 'spa', 'Perseguir ardientemente', 'Perseguir con vehemencia, cazar con intensidad abrasadora. Se usa para describir una persecución agresiva e implacable: Labán exige ''¿por qué me perseguiste con tanto ardor?'' (Gén 31:36), los israelitas persiguen a los filisteos en fuga (1 Sam 17:53), y los perseguidores de Jerusalén son ''más veloces que las águilas: nos persiguieron'' (Lam 4:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91725, 'spa', 'Puerta, portón', 'Puerta, portón: sentido primario y abrumadoramente dominante — una puerta o portón físico, la barrera movible que cierra una abertura en un muro, edificio o recinto. Atestiguada 84 veces en contextos diversos: puertas de casas (Gn 19:9-10; Jue 3:23-25), puertas de ciudades (Dt 3:5; Neh 3:3) y puertas del templo (1 R 6:34; Ez 41:24). La evidencia multilingüe es uniforme: español ''puerta'', francés ''porte'', alemán ''Tür''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91739, 'spa', 'Columna o panel de un rollo', 'Columna o panel de un rollo: en Jeremías 36:23, la palabra parece designar las ''columnas'' u hojas de un rollo, una extensión del concepto de hoja de puerta a los paneles de un documento escrito. El rey corta las דַּלְתוֹת del rollo con un cuchillo de escriba — los paneles del rollo se conceptualizan como hojas que se abren y cierran igual que una puerta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91740, 'spa', 'Tapa o cubierta de un cofre', 'Tapa o cubierta de un cofre: en 2 Reyes 12:9 la palabra describe la abertura o tapa de un cofre de recolección — literalmente ''en su puerta'' — donde el sacerdote Joiada perforó un agujero. El concepto de puerta se extiende a un panel de acceso de un contenedor en lugar de la entrada de una habitación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91756, 'spa', 'sangre (sustancia física)', 'Subconjunto del sentido literal que agrupa apariciones donde la sangre se describe como sustancia física en contextos sacrificiales, dietéticos y corporales. Sangre rociada en altares y dinteles (Éx 12:7; Lv 4:30), prohibición de ingestión (Gn 9:4; Lv 17:11-14), y sangre corporal en sentido médico o fisiológico (Lv 12:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91762, 'spa', 'sangre derramada, homicidio', 'Derramamiento de sangre y homicidio como extensión metonímica intensificada, donde el plural דָּמִים subraya la violencia reiterada o sistémica. ''Ciudad de sangres'' (Nah 3:1; Ez 22:2), ''sangre inocente'' vertida sin causa (Dt 19:10; Jer 22:3). Se solapa parcialmente con el sentido 3, pero enfatiza la acción criminal repetida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91776, 'spa', 'responsabilidad de sangre', 'Responsabilidad de sangre en sentido jurídico-forense: la obligación moral y legal que recae sobre quien derrama sangre. Las fórmulas ''su sangre sea sobre él'' (Lv 20:9), ''su sangre sobre su propia cabeza'' (Jos 2:19; 2 S 1:16) y ''líbrame de culpas de sangre'' (Sal 51:14) configuran un campo técnico del derecho bíblico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91822, 'spa', 'Ser semejante, parecerse', 'Ser semejante, parecerse: el sentido intransitivo básico del Qal/Nifal de tener parecido o ser similar a algo. El Cantar de los Cantares es el texto más rico aquí: el amado es como una gacela (Cnt 2:9, 17; 8:14), la estatura de la amada es como una palmera (Cnt 7:8). En los Salmos, el que sufre ''es semejante'' a un ave del desierto (Sal 102:6) y los humanos son ''como'' un soplo (Sal 144:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91823, 'spa', 'Comparar, asemejar', 'Comparar, asemejar: el Piel en su uso comparativo transitivo, donde el hablante traza activamente una analogía. El gran desafío monoteísta de Isaías — ''¿A quién compararéis a Dios? ¿A qué imagen lo asemejaréis?'' (Is 40:18, 25; 46:5) — emplea este sentido con fuerza retórica devastadora. Lamentaciones 2:13 pregunta ''¿con qué te compararé, oh hija de Jerusalén?''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91827, 'spa', 'Pensar, imaginar, planear, intentar', 'Pensar, imaginar, planear, intentar: el Piel en su extensión cognitiva, donde ''formar una semejanza'' se convierte en ''formar un pensamiento''. Jueces 20:5 dice ''intentaron matarme''; 2 Samuel 21:5 habla de ''el hombre que tramó contra nosotros''; Ester 4:13 advierte ''no imagines que escaparás''. El viaje semántico de la semejanza a la cognición es notable y se refleja en el cognado árabe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91831, 'spa', 'Hacerse semejante, autoasimilarse', 'Hacerse semejante, autoasimilarse: el Hitpael reflexivo en Isaías 14:14, donde el rey de Babilonia declara ''me haré semejante al Altísimo''. La fuerza reflexiva indica una autoexaltación deliberada y presuntuosa: no semejanza natural sino usurpación voluntaria de la semejanza divina. Una sola ocurrencia, pero cargada teológicamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91846, 'spa', 'Usar parábolas o símiles', 'Usar parábolas o símiles: un uso especializado del Piel en Oseas 12:10, donde Dios dice ''hablé por medio de los profetas y usé parábolas''. Aquí el verbo pasa de comparar cosas a la práctica profética de enseñar mediante comparaciones figurativas extendidas — el método parabólico en sí mismo. Una sola ocurrencia, pero significativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91849, 'spa', 'Ser destruido, perecer (Nifal)', 'Ser destruido, perecer (Nifal): ser destruido, perecer o ser cortado — el Nifal pasivo-reflexivo que expresa la ruina que sobreviene a ciudades, pueblos e individuos. Ar y Quir de Moab son ''destruidas en una noche'' (Isa 15:1), el pueblo de Dios ''perece por falta de conocimiento'' (Os 4:6), e Isaías declara ''estoy perdido'' ante la gloria divina (Isa 6:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91854, 'spa', 'Cesar, detenerse (Qal intransitivo)', 'Cesar, detenerse (Qal intransitivo): cesar, aquietarse o detenerse — el Qal intransitivo que indica la interrupción de una acción en curso. Jeremías ordena que sus ojos no ''cesen'' de derramar lágrimas (Jer 14:17), y el poeta de Lamentaciones dice que su ojo no ''se detiene'' sin descanso (Lam 3:49). Solo dos apariciones, ambas en contextos de llanto incesante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91858, 'spa', 'Destruir (Qal transitivo)', 'Destruir (Qal transitivo): destruir o arruinar activamente — el Qal transitivo donde Dios es el agente que corta. Dios declara ''destruiré'' a la hija de Sión, comparada con un prado ameno (Jer 6:2), y amenaza ''destruiré a tu madre'' en la acusación de Oseas contra Israel (Os 4:5). Dos apariciones, ambas con Dios como sujeto explícito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91863, 'spa', 'Semejanza o similitud abstracta', 'Semejanza o similitud abstracta: la cualidad de ser como algo. Central en la teología del imago Dei de Génesis 1:26 y 5:1-3, donde se empareja con tselem (''imagen''). En las visiones del trono de Ezequiel (1:5, 26; 10:1), funciona como marcador de aproximación: ''la semejanza de...'' señala que lo visto desafía una descripción completa. El español emplea consistentemente ''semejanza'' y el francés ''ressemblance''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91871, 'spa', 'Patrón, modelo o diseño concreto destinado a la reproducción', 'Patrón, modelo o diseño concreto destinado a la reproducción. En 2 Reyes 16:10 Acaz envía la demut del altar de Damasco al sacerdote Urías; aquí el español cambia a ''diseño'' en lugar de ''semejanza'', y el contexto exige un plano físico más que una similitud abstracta. Esta única ocurrencia se distingue del uso dominante del término, mostrando una extensión práctica y arquitectónica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91873, 'spa', 'Silencio o quietud', 'Quietud, reposo, silencio, cesación: una inactividad que puede ser apacible o perturbadora según el contexto. En Sal 83:1 el salmista suplica a Dios que rompa su silencio (אַל־דֳּמִי לָךְ), en paralelo con «no estés sordo» y «no te quedes quieto». Isaías 62:6-7 lo usa dos veces: los centinelas no deben callar y no deben dar reposo a Dios. En Is 38:10, Ezequías habla de «la quietud de mis días» (בִּדְמִי יָמַי), refiriéndose a la plenitud de la vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91875, 'spa', 'Ser silenciado, perecer, ser destruido', 'Ser silenciado, perecer, ser destruido: formas del Nifal donde el silencio se impone como destrucción o juicio divino. Los impíos ''enmudecen en tinieblas'' (1 S 2:9); Jeremías declara que los jóvenes de Damasco, Cedar y Babilonia ''serán silenciados'', es decir, destruidos (Jer 49:26; 50:30). En Jer 25:37 ''los apriscos de paz enmudecen a causa de la ardiente ira del SENOR''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91876, 'spa', 'Calmar, aquietar (Piel causativo)', 'Calmar, aquietar (Piel causativo): provocar deliberadamente un estado de quietud o tranquilidad en otro. Salmo 131:2 — ''ciertamente he calmado y aquietado mi alma, como un niño destetado junto a su madre'' — es la única instancia clara, usando el Piel para expresar una pacificación tierna y maternal de la turbación interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91877, 'spa', 'Estar en silencio, guardar silencio, abstenerse de hablar o hacer ruido', 'Estar en silencio, guardar silencio, abstenerse de hablar o hacer ruido: el sentido intransitivo básico del Qal. Aarón ''calló'' tras la muerte de sus hijos (Lv 10:3), un silencio de duelo y sumisión. El sabio ''calla'' en tiempo de maldad (Am 5:13). El salmista ordena a su propia alma ''estar quieta'' ante Dios (Sal 4:4; 62:5). Lamentaciones 2:10 y 3:28 describen el silencio del exilio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91881, 'spa', 'Hacer callar, silenciar por destrucción (Hifil causativo)', 'Hacer callar, silenciar por destrucción (Hifil causativo): imponer silencio mediante una fuerza abrumadora y aniquiladora. En Jeremías 8:14 el pueblo confiesa ''el SENOR nuestro Dios nos ha destruido'', usando el Hifil para marcar a Dios como el agente externo que reduce a una nación al silencio mediante un juicio devastador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91886, 'spa', 'Detenerse, cesar, parar', 'Detenerse, cesar, parar: cesación física del movimiento en lugar de ausencia de sonido. La orden de Josué al sol — ''Sol, detente en Gabaón'' (Jos 10:12) — y su cumplimiento, ''el sol se detuvo'' (Jos 10:13), son las instancias definitivas. 1 Samuel 14:9 lo usa para soldados que se quedan quietos. Job 30:27 y Salmo 35:15 extienden el concepto a la agitación interior que no quiere ''calmarse''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91904, 'spa', 'Susurro o calma', 'Susurro o silencio profundo, con tres apariciones en contextos de encuentro divino o liberación. 1 Reyes 19:12 usa el constructo «voz de susurro suave» (קוֹל דְּמָמָה דַקָּה): la presencia de Dios en la quietud tras fenómenos dramáticos. Job 4:16 lo empareja con «voz»: un susurro sobrenatural en la visión de Elifaz. Salmo 107:29 describe la tormenta transformada «en calma».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91905, 'spa', 'Estiércol, abono', 'Estiércol o abono animal, utilizado metafóricamente para describir cadáveres insepultos abandonados a descomponerse sobre el suelo como desecho sin valor. El sustantivo דֹּמֶן (domen) es cognado del árabe ''dimn'' (estiércol). Las traducciones al español emplean consistentemente ''estiércol'' con el marcador de símil ''como'', reflejando su uso figurado en contextos de juicio profético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91911, 'spa', 'Lágrimas derramadas en duelo, lamentación u oración ferviente', 'Lágrimas derramadas en duelo, lamentación u oración ferviente: recogidas por Dios como testimonio de sufrimiento (Sal 56:8), empapando el lecho del salmista (Sal 6:6), fluyendo como fuente en la angustia profética de Jeremías (Jer 9:1; 14:17) y moviendo a Dios a sanar a Ezequías (2 R 20:5). El español ''lágrimas'', el francés ''larmes'' y el alemán ''Träne'' confirman una traducción uniforme en las 23 ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91923, 'spa', 'Damasco (ciudad) — El nombre propio Damasco (דַּמֶּשֶׂק/דַּרְמֶשֶׂק), la antigua', 'Damasco (ciudad) — El nombre propio Damasco (דַּמֶּשֶׂק/דַּרְמֶשֶׂק), la antigua capital de Aram (Siria) ubicada en una llanura bien irrigada al este de la cordillera del Antilíbano. Funciona como punto de referencia geográfico en las narrativas patriarcales (Gn 14:15; 15:2), como centro político del poder arameo rival de Israel y Judá (1 R 11:24; 2 R 8:7-9; 16:10), y como símbolo profético de juicio extranjero (Is 7:8; 17:1; Am 1:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91937, 'spa', 'Dan (nombre propio)', 'Dan (nombre propio): el nombre propio Dan, que abarca al patriarca (Gn 30:6; 49:16-17), la tribu descendiente de él (Nm 1:38-39; Jue 18) y la ciudad fronteriza del norte que ancló la frase proverbial ''desde Dan hasta Beerseba'' (Jue 20:1; 2 S 3:10). El significado etimológico ''juez'' (de דִּין) se activa en la bendición de Jacob (Gn 49:16, ''Dan juzgará a su pueblo''). La evidencia interlingüística es perfectamente uniforme: Dan se mantiene invariable en todas las traducciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91944, 'spa', 'Este, ese, así (demostrativo arameo)', 'Este, ese, así (demostrativo arameo): pronombre demostrativo arameo que significa ''este, ese, así''. Las 58 apariciones se concentran en Esdras 4-7 y Daniel 2-7, las secciones arameas de la Biblia hebrea. El español distingue género (''este/esta''), el francés usa ''ceci'' y el alemán ''dieses'', cada uno correspondiendo naturalmente a una única función deíctica. Con la preposición כְּ se extiende al sentido adverbial ''como esto, así'' (Dn 2:10; 7:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91952, 'spa', 'El danita', 'Adjetivo gentilicio que marca la afiliación tribal con Dan. Siempre aparece con el artículo (הַדָּנִי). En Jueces 13:2 identifica al clan de Manoa; en Jueces 18:1, 11, 30 se emplea durante la narración de la migración de la tribu en busca de territorio. 1 Crónicas 12:36 enlista a guerreros danitas que se unieron a David. Funciona como designación étnica colectiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91953, 'spa', 'Daniel (nombre propio) — El nombre propio ''Dios es mi juez'', que designa princip', 'Daniel (nombre propio) — El nombre propio ''Dios es mi juez'', que designa principalmente al profeta-sabio del exilio que interpreta sueños para Nabucodonosor y recibe visiones apocalípticas en Babilonia (Dn 1-12). Ezequiel cita a un personaje llamado Daniel como modelo de rectitud junto a Noé y Job (Ez 14:14, 20) y como extraordinariamente sabio (Ez 28:3). También lo llevan un hijo de David y Abigail (1 Cr 3:1) y un sacerdote postexílico de la línea de Itamar (Esd 8:2; Neh 10:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91961, 'spa', 'Daniel (nombre propio)', 'Daniel (nombre propio): el nombre personal Daniel (דָּנִיֵּאל, ''Dios es mi juez''), que se refiere principalmente al profeta exílico y sabio que sirvió en las cortes de Nabucodonosor, Belsasar y Darío (Dn 2:13-6:28). Su nombre también pertenece a un hijo de David (1 Cr 3:1) y a un sacerdote postexílico firmante del pacto (Neh 10:7). La transliteración uniforme en español, francés y alemán confirma que se trata de un nombre propio fijo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91968, 'spa', 'Conocimiento, opinión', 'Conocimiento, opinión o juicio meditado: una formulación deliberada de entendimiento. En Job 32:6, 10, 17, Elihú lo usa para referirse a su propia opinión que se siente compelido a expresar. Job 36:3 amplía el alcance cuando Elihú atribuye conocimiento a su Hacedor. Job 37:16 habla de Dios como «perfecto en conocimiento» (תְּמִים דֵּעִים), donde el plural expresa plenitud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91969, 'spa', 'Conocimiento, entendimiento', 'Conocimiento o conciencia como cualidad abstracta. Se aplica a la omnisciencia divina (1 Sam 2:3, donde el plural de''ot enfatiza la plenitud del saber de Dios), a la comprensión humana de los caminos divinos (Sal 73:11; Isa 11:9) y a la instrucción profética o sapiencial (Isa 28:9; Jer 3:15). Apunta a un saber experiencial, no a datos superficiales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91973, 'spa', 'Nombre propio gadita', 'Deuel: nombre personal de un gadita, padre de Eliasaf, quien lideró la tribu de Gad en el censo del desierto y las ofrendas de dedicación del tabernáculo (Nm 1:14; 7:42, 47; 10:20). La LXX lee consistentemente Ραγουηλ (Raguel), y el pasaje paralelo de Nm 2:14 tiene Reuel, lo que indica una antigua confusión escribal entre dálet y resh. El nombre probablemente significa «conocido de Dios».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91974, 'spa', 'Apagarse, extinguirse', 'El Qal imperfecto describe el proceso de apagarse: una llama que parpadea hacia la oscuridad. Casi todas las ocurrencias son figuradas: ''la lámpara de los impíos'' se apagará, simbolizando el fin de su fortuna y legado (Job 18:5-6; 21:17; Prov 13:9; 20:20; 24:20). ''Se apaga'' capta el matiz de voz media.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91976, 'spa', 'Ser extinguido, sofocado', 'Las formas Nifal y Pual perfectivas denotan el estado consumado de haber sido extinguido. En Job 6:17 los wadis secos ''son hechos extintos'' (nid''akhu), mientras que Salmo 118:12 compara a los asaltantes con espinos ya apagados. Isaías 43:17 describe fuerzas enemigas que ''se apagaron'' como una mecha sofocada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91979, 'spa', 'Conocimiento, discernimiento', 'Conocimiento, discernimiento: conocimiento o discernimiento abstracto — la capacidad intelectual y moral de percibir, comprender y evaluar. Cubre la gran mayoría de las apariciones en todas las formas gramaticales (absoluta, constructa, con sufijos y preposiciones). Español ''conocimiento'', francés ''connaissance'' y alemán ''Erkenntnis'' confirman uniformemente su carácter de sustantivo de facultad cognitiva. Textos clave incluyen Proverbios 2:10 (''cuando el conocimiento entre en tu corazón'') y el ''árbol del conocimiento'' de Génesis 2:9.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91988, 'spa', 'Conocer, saber (infinitivo)', 'Conocer, saber (infinitivo): infinitivo constructo Qal de יָדַע: ''conocer, saber'' — funcionando como gerundio o cláusula de propósito, preservando fuerza verbal más que referencia puramente nominal. Las traducciones interlingüísticas se dividen entre formas nominales y verbales: alemán ''könnte wissen'', español ''conocimiento de''. Se encuentra en Jueces 3:2 (para que las generaciones posteriores aprendieran la guerra conociéndola) e Isaías 48:4 (''porque sabía que eras obstinado'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (91998, 'spa', 'Golpear o arrear', 'Los tres contextos muestran un impacto físico contundente: arrear animales cruelmente (Gn 33:13), aporrear una puerta con violencia (Jue 19:22, «se golpearon hasta agotarse») y llamar a la puerta para entrar (Cnt 5:2). Las glosas interlingüísticas reflejan de manera consistente este doble rango semántico de fuerza aplicada tanto a ganado como a puertas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92000, 'spa', 'Delgado, flaco, enjuto', 'Referido a seres vivos que están flacos, enjutos o demacrados, sobre todo las vacas delgadas y las espigas marchitas en el sueño del faraón (Gn 41:3-7, 23-24). El adjetivo modifica ''carne'' (basar) para transmitir una flacura alarmante que anuncia hambruna venidera. Las seis apariciones se concentran en la narrativa de José, marcando a דַּק como la palabra propia del presagio de escasez.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92001, 'spa', 'Fino, menudo, en polvo', 'Referido a sustancias y partículas que son finas, menudas o pulverizadas. El maná se describe como ''fino, escamoso, fino como la escarcha'' (Éx 16:14), usando דַּק dos veces en un solo versículo para enfatizar su textura delicada. Se aplica también al incienso molido (Lv 16:12), al cabello fino (Lv 13:30) y al polvo tan menudo que se vuelve insignificante (Is 29:5; 40:15). El árabe daqiq confirma esta raíz semítica compartida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92005, 'spa', 'Enano, de talla reducida', 'Un defecto físico que hace que una persona sea de estatura reducida o raquítica, enumerado entre las imperfecciones descalificantes para el servicio sacerdotal (Lv 21:20). Ya se trate de enanismo o de una condición debilitante, el sentido central de דַּק — tamaño insuficiente — se aplica aquí al cuerpo humano. El contexto de pureza sacerdotal señala una deficiencia física visible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92007, 'spa', 'Tenue, apacible, suave', 'Referido a un sonido delgado, suave o apacible: la célebre ''voz apacible y delicada'' (qol demamah daqqah) que Elías escuchó en Horeb (1 R 19:12). Después del viento, el terremoto y el fuego, la presencia divina vino en un sonido tan tenue que era apenas perceptible. Este sentido extiende a דַּק del ámbito visual y táctil al auditivo, sugiriendo algo reducido a su forma más delicada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92010, 'spa', 'Ser o quedar fino', 'El sentido estativo intransitivo: ser o quedar fino, delgado, reducido a polvo. Describe el estado final después de la molienda, no el acto en sí. Se encuentra en la narrativa del becerro de oro, donde Moisés molió hasta que el material ''quedó fino'' como polvo (Éx 32:20; Dt 9:21), y en la receta del incienso molido ''fino'' (Éx 30:36).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92011, 'spa', 'Ser molido o triturado', 'El sentido pasivo (Hofal): ser triturado o molido por un agente externo. Atestiguado únicamente en Isaías 28:28, donde el grano para pan se describe como finalmente molido, aunque el labrador no lo trilla eternamente. La forma pasiva lo distingue claramente del Hifil activo, indicando que el sujeto recibe la acción de moler.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92012, 'spa', 'Triturar, pulverizar', 'El sentido causativo transitivo: triturar, machacar, pulverizar o desmenuzar algo hasta convertirlo en polvo fino. Destaca en las purgas cultuales donde los reyes destruyen objetos idolátricos (2 R 23:6, 15; 2 Cr 15:16; 34:4) y en el salmo de victoria de David donde los enemigos son pisoteados como polvo (2 S 22:43). La acción implica reducción física enérgica y deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92022, 'spa', 'Desmenuzar, quebrantar (Hafel)', 'Desmenuzar, quebrantar (Hafel): acción causativa de triturar hasta reducir a polvo. Es el sentido dominante, presente en las visiones apocalípticas de Daniel: la piedra cortada sin manos que golpea y destroza la estatua compuesta (Dn 2:34, 40, 44-45), y la cuarta bestia que aplasta y devora todo a su paso (Dn 7:7, 19, 23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92028, 'spa', 'Ser desmenuzado (Peal pasivo)', 'Ser desmenuzado (Peal pasivo): forma intransitiva o pasiva que describe el estado de haber sido pulverizado. Daniel 2:35 emplea esta forma para narrar las consecuencias: todos los materiales de la imagen ''fueron desmenuzados juntos'' y se volvieron como tamo en una era de verano. Este pasivo completa el cuadro iniciado por el Hafel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92030, 'spa', 'Traspasar, atravesar', 'Traspasar, atravesar: acción de atravesar con un arma (Qal activo), siempre describiendo una estocada fatal o casi fatal. Fineas traspasa a la pareja transgresora (Nm 25:8), el escudero de Abimelec lo atraviesa a petición suya (Jue 9:54), y Saúl hace la misma petición a su propio escudero (1 S 31:4; 1 Cr 10:4). Zacarías 12:10 emplea el Qal perfecto en la profecía mesiánica: ''mirarán a mí, a quien traspasaron.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92031, 'spa', 'Ser traspasado, ser herido', 'Ser traspasado, ser herido: forma pasiva (participio Pual y Nifal) que describe a quienes han sido atravesados por la espada y yacen muertos. Isaías 13:15 profetiza que en la caída de Babilonia ''todo el que sea hallado será traspasado,'' y Jeremías 51:4 usa el mismo lenguaje para las víctimas en las calles caldeas. Lamentaciones 4:9 contrasta a los ''traspasados por la espada'' con quienes mueren de hambre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92041, 'spa', 'Generación sucesiva', 'Generación (arameo) — un lapso de sucesión humana, usado exclusivamente en la fórmula duplicada דָּר וְדָר (''generación y generación'') para declarar la perpetuidad de la soberanía de Dios. En Dan 4:3 y 4:34, Nabucodonosor confiesa que el dominio de Dios perdura ''con generación y generación''. La duplicación intensifica el sentido hacia ''cada generación sucesiva'' o ''por todas las edades''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92047, 'spa', 'Sur, dirección meridional', 'Sur, dirección meridional: sustantivo geográfico direccional que significa ''sur'' o ''el sur,'' empleado principalmente en el hebreo bíblico poético y tardío. Concentrado en la visión del templo de Ezequiel (12 de 17 apariciones), donde designa la puerta sur (שַׁעַר הַדָּרוֹם), las cámaras meridionales y la orientación sur, consistentemente opuesto a צָפוֹן (''norte''). Deuteronomio 33:23 y Job 37:17 lo usan fuera de Ezequiel para la dirección y el viento del sur respectivamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92052, 'spa', 'Libertad', 'Libertad o liberación de la servidumbre, término técnico para la emancipación proclamada en el año del Jubileo. Levítico 25:10 lo empareja con qara (''proclamar''): ''proclamaréis libertad a todos sus habitantes.'' Isaías 61:1 lo aplica mesiánicamente y Jeremías 34:8-17 registra el pacto de liberación de Sedequías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92054, 'spa', 'Fluido, que fluye', 'Que fluye libremente, describiendo la mirra líquida que gotea de forma natural. Éxodo 30:23 especifica mor-deror (''mirra fluida'') como primer ingrediente del aceite sagrado de unción: la calidad más selecta que mana sin prensado mecánico. Ambos sentidos comparten la idea raíz de movimiento sin restricción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92056, 'spa', 'Darío (nombre propio)', 'Darío (nombre propio): nombre real Darío (en hebreo דָּרְיָוֶשׁ, del persa antiguo Darayavaush), aplicado a reyes de la era persa. La mayoría de las apariciones se refieren a Darío I Histaspes, bajo cuyo reinado se reconstruyó el templo de Jerusalén (Esd 4:5; Hag 1:1, 15; Zac 1:1, 7). El nombre también designa a Darío el Medo en Daniel (Dn 9:1; 11:1) y posiblemente a Darío III en Nehemías 12:22. La fórmula cronológica ''en el año X de Darío'' es la más frecuente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92058, 'spa', 'Darío (nombre real)', 'El nombre real persa Darío (דָּרְיָוֶשׁ), del persa antiguo Dārayavauš, que designa al menos dos figuras: Darío I Histaspes, bajo cuyo reinado se reconstruyó el Segundo Templo (Esd 4:24; 6:1, 12-15; Hag 1:1; Zac 1:1), y el misterioso ''Darío el Medo'' de Daniel (Dn 6:1, 6, 9, 25, 28). Las traducciones van desde transliteraciones cercanas al hebreo hasta la forma convencional europea ''Darío''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92062, 'spa', 'Tensar el arco', 'Tensar el arco: uso técnico-militar derivado de la acción física de pisar el extremo inferior del arco para tensarlo y encordarlo. Es un sentido lexicalizado propio, no una metáfora: 1 Cr 5:18 y 8:40 describen guerreros que ''tensan el arco'' como destreza militar, y Sal 11:2 advierte que los impíos ''tensan su arco''. Cuenta con 20 ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92063, 'spa', 'Pisar, pisotear', 'Pisar, pisotear: el sentido básico en Qal de poner el pie sobre algo, ya sea pisar uvas en el lagar (Isa 63:3), caminar sobre territorio conquistado (Dt 1:36; 11:24; Jos 1:3) o pisotear enemigos y umbrales (1 Sam 5:5). Abarca 30 ocurrencias que cubren todo el espectro del contacto físico del pie con el suelo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92079, 'spa', 'Guiar, conducir', 'Guiar, conducir: causativo Hifil que significa guiar, conducir o hacer caminar por una senda, casi siempre con Dios como sujeto. Sal 25:5 (''guíame en tu verdad'') y Pr 4:11 (''te he guiado por sendas de rectitud'') son pasajes fundamentales. El salto metafórico de pisar físicamente a guiar divinamente es tan completo que las lenguas receptoras abandonan la imagen del pisoteo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92090, 'spa', 'Hacer pisotear, trillar', 'Hacer pisotear, trillar: causativo Hifil que conserva la fuerza física o agrícola del Qal. Jue 20:43 describe enemigos pisoteados; Jer 51:33 presenta a Babilonia como era a punto de ser trillada. Cuenta con 3 ocurrencias donde el causativo retiene la violencia o el trabajo agrícola del sentido base.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92108, 'spa', 'Marchar, avanzar', 'Marchar, avanzar: una única ocurrencia ambigua en Nm 24:17, donde Balaam profetiza que ''una estrella saldrá de Jacob'', y דָּרַךְ describe el movimiento de la estrella, traducido como ''marchará'' o ''avanzará''. Sugiere un desplazamiento procesional y solemne, distinto tanto del pisoteo violento como del tensar el arco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92118, 'spa', 'camino, senda, ruta', 'Un camino físico, senda o ruta: la vía concreta por la que las personas caminan o viajan, con 376 apariciones. Abarca rutas con nombre («el camino de la tierra de los filisteos», Éx 13:17), caminos entre ciudades (Gn 35:19), sendas en el desierto (Gn 24:27; 28:20) e incluso rastros de animales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92119, 'spa', 'modo de vida, conducta', 'Variante del sentido metafórico: el modo de vida, la conducta moral o el comportamiento habitual de una persona, con 318 apariciones. Conforma la gran extensión ética del vocablo, donde «camino» designa la orientación espiritual y moral que define al justo o al impío ante Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92157, 'spa', 'viaje, travesía', 'Un viaje, expedición o distancia recorrida: 15 apariciones donde el énfasis recae en el acto de viajar. Jacob prepara provisiones «para el viaje» (Gn 42:25; 45:21, 23), Elías es fortalecido para su travesía al Horeb (1 R 19:7) y el viaje de tres días al desierto se convierte en fórmula del Éxodo (Éx 3:18; 8:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92199, 'spa', 'dirección, rumbo', 'Una única aparición en 1 Reyes 18:43, donde Elías envía a su siervo a mirar «hacia el mar» (דֶּרֶךְ־יָם, «el camino del mar»). El uso sugiere una función direccional o locativa — «en dirección a» — que oscila entre el sentido concreto de camino y un adverbio espacial puro, casi una cuasi-preposición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92201, 'spa', 'costumbre, modo', 'Costumbre, modo o manera característica de hacer algo: sentido raro que aparece solo dos veces, en Gn 19:31 («la costumbre de toda la tierra», es decir, la unión sexual) y Gn 31:35 («la costumbre de las mujeres», es decir, la menstruación). Aquí דֶּרֶךְ se ha vuelto plenamente abstracto: «la manera en que se hacen las cosas».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92222, 'spa', 'Moneda de oro', 'Dárico o dracma — moneda de oro del período persa, mencionada en el contexto de contribuciones voluntarias para la reconstrucción del templo de Jerusalén. En Esdras 2:69, los exiliados que regresan donan 61.000 dáricos de oro; Nehemías 7:70–72 registra aportes similares. Ambas formas son probablemente préstamos lingüísticos del persa o del griego, y la incertidumbre numismática persiste en las traducciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92226, 'spa', 'buscar, procurar', 'El sentido más amplio y frecuente: buscar a alguien o algo, ya sea de manera física, espiritual o metafórica. ''Buscad al Señor y su fortaleza'' (1 Cr 16:11) ejemplifica el registro devocional. El árabe طلب conserva el matiz de persecución activa, mientras que el español buscar lo traduce de modo directo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92228, 'spa', 'consultar, inquirir', 'Sentido especializado de buscar orientación divina: consultar a Dios, a un profeta o a un oráculo. Rebeca ''consultó al Señor'' acerca de sus mellizos (Gn 25:22), y los reyes consultaban al profeta antes de ir a la guerra (1 R 22:5). El árabe سأل (''preguntar'') capta la cualidad formal y deliberativa de esta indagación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92231, 'spa', 'ser consultado (Nifal)', 'El Nifal pasivo-reflexivo describe a Dios permitiendo o rehusando ser consultado. El ''no me dejaré consultar por vosotros'' de Ezequiel (Ez 20:3, 31) contrasta tajantemente con el ''fui hallado por los que no me buscaban'' de Isaías (Is 65:1). Este sentido revela una teología de la disponibilidad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92256, 'spa', 'investigar, examinar', 'Investigación minuciosa de un asunto, especialmente en contextos judiciales. Deuteronomio exige que las acusaciones se investiguen con diligencia (Dt 13:14; 17:4; 19:18). El árabe بحث (''examinar'') y el alemán untersuchen transmiten la precisión forense que este sentido demanda: una búsqueda metódica de la verdad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92276, 'spa', 'ser requerido (Nifal pasivo)', 'El participio pasivo Nifal describe un estado de ser requerido o buscado. El ''Buscada, ciudad no abandonada'' de Isaías (Is 62:12) transforma el verbo en título de dignidad restaurada. En Gn 42:22 (''su sangre es demandada'') resuena el sentido judicial en voz pasiva. El árabe مطلوب lo refleja con precisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92296, 'spa', 'cuidar, atender', 'Extensión figurada en la que buscar se convierte en cuidar: Dios ''cuida'' la tierra (Dt 11:12), y el salmista lamenta que nadie ''busca mi alma'' (Sal 142:4). Este sentido tiende un puente entre la indagación intelectual y la atención compasiva, mostrando cómo la búsqueda persistente puede tornarse en solicitud tierna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92311, 'spa', 'requerir, demandar', 'Sentido jurídico y pactual: requerir, demandar o pedir cuentas, especialmente por derramamiento de sangre. Dios declara ''vuestra sangre la demandaré'' (Gn 9:5), estableciendo un principio de responsabilidad. En 2 Cr 24:22 (''que el Señor lo vea y lo demande'') se aprecia el sentido de ajuste de cuentas divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92344, 'spa', 'Hierba, vegetación tierna', 'Hierba joven y tierna que brota del suelo, la vegetación fresca producida en la creación (Gn 1:11-12) y sostenida por la lluvia y el cuidado divino. Usada 14 veces, denota consistentemente la etapa más temprana y tierna del crecimiento vegetal. La tierra תַּדְשֵׁא דֶּשֶׁא (''produce hierba'', Gn 1:11) en una construcción de acusativo cognado. Las traducciones multilingües convergen en ''hierba'', ''pasto'', ''vegetación''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92349, 'spa', 'Trilla', 'Un participio femenino singular Qal de la raíz separada דּוּשׁ, que significa ''trillar'': el acto de separar el grano de la cáscara. En Jer 50:11, Babilonia se compara con una becerra que ''trilla'' (דָּשָׁה), deleitándose en la abundancia mientras pisotea. Este sentido pertenece a un dominio semántico completamente diferente al del sustantivo de hierba, un caso de superposición homográfica en hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92355, 'spa', 'Estar gordo, ser enriquecido', 'Estar gordo, ser enriquecido: sentido intransitivo de volverse gordo, próspero o enriquecido, en formas Qal, Pual y Nifal. Deuteronomio 31:20 advierte que Israel engordará y se volverá a otros dioses, mientras que Proverbios 11:25 promete que el alma generosa ''será prosperada.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92356, 'spa', 'Retirar las cenizas', 'Retirar las cenizas: sentido denominativo del Piel derivado de deshen (cenizas grasientas), que significa limpiar el residuo grasiento del altar de los sacrificios. Éxodo 27:3 enumera utensilios hechos ''para retirar sus cenizas,'' y Números 4:13 prescribe la misma limpieza durante el transporte del tabernáculo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92357, 'spa', 'Engordar, enriquecer', 'Engordar, enriquecer: sentido activo del Piel de hacer gordo, bien nutrido o robusto a alguien o algo. Proverbios 15:30 dice que la buena noticia ''engorda los huesos,'' expresando el vigor físico que proviene de la alegría.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92359, 'spa', 'Aceptar con favor', 'Aceptar con favor: sentido metafórico del Piel de aceptar o mirar un sacrificio con favor divino, representando la ofrenda como hecha ''gorda'' y por tanto agradable. En el Salmo 20:3 el adorador ora para que Dios ''acepte con agrado'' el holocausto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92360, 'spa', 'Estar saciado, estar ahíto', 'Estar saciado, estar ahíto: sentido reflexivo del Hitpael de quedar repleto o harto de grasa, indicando una saciedad excesiva o espantosa. Isaías 34:6 describe la espada del Señor ''engrosada'' con la grasa de corderos y cabras en el juicio apocalíptico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92364, 'spa', 'Ungir con aceite', 'Ungir con aceite: sentido del Piel de ungir la cabeza con aceite o grasa como señal de fiesta, honor y gozo. En el Salmo 23:5 el anfitrión-pastor ''ungiste mi cabeza con aceite,'' distinguiéndose de la simple idea de engordar al referirse a la unción festiva o cosmética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92365, 'spa', 'Rico y vigoroso', 'Se aplica a los frutos de la tierra (Is 30:23), a los justos como árboles frondosos (Sal 92:14) y a los prósperos o vigorosos de la tierra (Sal 22:29). Las glosas destacan riqueza, plenitud de savia y prosperidad, expresando abundancia tanto material como espiritual. La palabra connota salud floreciente y fecundidad, no mero peso físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92366, 'spa', 'Cenizas grasientas (sacrificiales)', 'Cenizas grasientas: el residuo impregnado de grasa producido al quemar animales sacrificiales en el altar. Término técnico sacerdotal que aparece 8 veces, exclusivamente en contextos rituales. Levítico prescribe la remoción de דֶּשֶׁן del altar: el sacerdote se viste de lino, levanta las cenizas, se cambia de ropa y las lleva fuera del campamento (Lv 6:10-11). También aparece en Lv 1:16 con las aves sacrificiales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92368, 'spa', 'Gordura, riqueza, abundancia', 'Gordura, riqueza o abundancia como cualidad de prosperidad, fertilidad y bendición divina. El olivo en la fábula de Jotam se niega a abandonar su דֶּשֶׁן, su aceite rico (Jue 9:9). El salmista declara que el pueblo de Dios se sacia ''de la abundancia (דֶּשֶׁן) de tu casa'' (Sal 36:8) y que el alma se satisface ''como de médula y grosura'' (Sal 63:5). Dios corona el año con bondad y los senderos destilan abundancia (Sal 65:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92376, 'spa', 'Sentido primario de una ley, regulación o estatuto vinculante con fuerza legal p', 'Sentido primario de una ley, regulación o estatuto vinculante con fuerza legal permanente, que abarca 19 de las 22 ocurrencias. En Est 1:8 la ley del rey rige el banquete (''nadie era obligado''), y en Est 1:13,15 se consulta a expertos legales sobre lo que ''la ley'' exige. Las glosas multilingues convergen en terminología jurídica: español ''ley'', francés ''loi'', alemán ''Gesetz'', distinguiéndolo como normativa vigente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92383, 'spa', 'Sentido judicial poco frecuente en Est 4', 'Sentido judicial poco frecuente en Est 4:11, donde דָּת funciona como sentencia, pena o veredicto aplicado a una persona específica. Quien se acerque al rey sin ser invitado tiene ''una sola ley'' (אַחַת דָּתוֹ): la muerte, a menos que el rey extienda su cetro de oro. Aquí la ''ley'' se ha convertido en una consecuencia punitiva específica, no en un código de regulaciones ni en una proclamación real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92384, 'spa', 'Sentido más específico de un decreto o edicto real', 'Sentido más específico de un decreto o edicto real: una orden autoritativa emitida para una ocasión particular, no un estatuto permanente. Esdras 8:36 informa que los edictos del rey fueron entregados a los sátrapas, y Est 4:8 menciona una copia del ''decreto escrito'' (כְּתָב הַדָּת) emitido para la destrucción de los judíos. El español ''decreto'' y el francés ''décret'' lo distinguen del sentido de ley general.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92387, 'spa', 'Ley, regulación, estatuto', 'El sentido más amplio y frecuente: un cuerpo de leyes, un código legal o un conjunto de regulaciones vinculantes para una comunidad. En Esdras 7:12-26 se refiere siete veces a la ''ley de tu Dios'' o la ''ley del rey'', denotando siempre un marco legal establecido y no un mandato aislado. Las traducciones convergentes en múltiples idiomas confirman este sentido de autoridad legal obligatoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92391, 'spa', 'Decreto real, edicto', 'Un sentido más restringido: un decreto real o edicto específico emitido por autoridad soberana. En Daniel 2:13 y 2:15, cuando la sentencia de muerte del rey sale contra los sabios, la palabra designa no un código legal sino un mandato autoritativo único. El español pasa de ''ley'' a ''decreto'', señalando una clara distinción semántica reconocida en múltiples lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92393, 'spa', 'Sentencia, veredicto judicial', 'El sentido más raro y preciso: una sentencia o veredicto judicial, la pena impuesta a una persona y no la ley bajo la cual se dicta. En Daniel 2:9, Nabucodonosor declara que los sabios han acordado una sola sentencia (דָּת) entre ellos. El español lo traduce como ''sentencia'', distinguiéndolo tanto de la ley general como del decreto real específico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92399, 'spa', 'Datán — nombre propio que identifica a un rubenita, hijo de Eliab, quien junto c', 'Datán — nombre propio que identifica a un rubenita, hijo de Eliab, quien junto con Abiram encabezó una rebelión contra Moisés y Aarón en el desierto (Nm 16:1, 12). Las diez ocurrencias se refieren a este único individuo a lo largo de la narrativa de Coré (Nm 16:1-27), la recapitulación genealógica (Nm 26:9) y las referencias retrospectivas posteriores (Dt 11:6; Sal 106:17). El nombre aparece con conjunciones y preposiciones pero sin variación referencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92402, 'spa', 'Topónimo bíblico', 'Este nombre propio designa consistentemente una ubicación geográfica específica en los relatos de José (Gn 37:17, mencionada dos veces) y de Eliseo (2 R 6:13). Las traducciones preservan el nombre en lugar de traducirlo, reflejando su función como topónimo fijo en la geografía bíblica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92406, 'spa', 'Interjección exclamativa de regodeo malicioso o escarnio triunfante, puesta típi', 'Interjección exclamativa de regodeo malicioso o escarnio triunfante, puesta típicamente en boca de los enemigos (Sal 35:21, 25; 40:15; Ez 25:3; 26:2; 36:2). De modo singular, expresa la feroz exaltación del caballo de guerra (Job 39:25). Traducciones como «ajá» en español, «ha» en francés y «aha» en alemán captan su fuerza visceral y emotiva en las doce ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92408, 'spa', 'Volverse vano, vaciarse', 'Volverse vano, obrar con vacuidad o quedar reducido a la inutilidad, describiendo el deterioro moral y espiritual por buscar cosas vacías. El Qal expresa la futilidad autoinfligida: 2 Reyes 17:15 y Jeremías 2:5 emplean el punzante juego de palabras «siguieron הֶבֶל y se hicieron vanos». El Salmo 62:10 advierte contra desmoralizarse por la ganancia ilícita. El Hifil en Jeremías 23:16 describe a falsos profetas que llenan de ilusión a otros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92409, 'spa', 'Vanidad, futilidad, absurdo', 'Vanidad, futilidad, absurdo: el sentido abstracto dominante, nota clave del Eclesiastés, donde el esfuerzo humano, la sabiduría, el placer y el trabajo son declarados הֶבֶל ''bajo el sol''. No es nihilismo, sino el reconocimiento de que las empresas terrenales no pueden asegurar un sentido duradero por sí solas (Ecl 1:2; 12:8). Job emplea la misma palabra al declarar que sus días son הֶבֶל (Job 7:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92411, 'spa', 'Ídolos, dioses falsos', 'Ídolos, dioses falsos: la aplicación polémico-teológica a los ídolos y dioses falsos, predominantemente en plural הֲבָלִים. Deuteronomio advierte que Israel provocó a Dios ''con sus הֲבָלִים'' (Dt 32:21), y Jeremías condena a los dioses de las naciones como ''הֶבֶל sin aliento'' (Jer 10:14-15; 51:18). La palabra es un insulto teológico deliberado: los ídolos no solo son inútiles, sino literalmente insustanciales, vaciedades vaporosas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92423, 'spa', 'Vapor, aliento, soplo fugaz', 'Vapor, aliento, soplo fugaz: el sentido concreto y literal de un soplo, una bocanada o un vapor, algo físicamente insustancial que se disipa casi al instante. Sal 62:9 pone a la humanidad en una balanza y la encuentra más ligera que הֶבֶל, mientras Sal 144:4 dice que los días humanos son ''como הֶבֶל''. Isa 57:13 lo empareja con el viento: ''un soplo se los llevará a todos''. Esta imagen física es la raíz experiencial de la que brotan los sentidos abstractos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92433, 'spa', 'Hevel (Abel)', 'El nombre propio Hevel (Abel), segundo hijo de Adán. Las ocho ocurrencias se encuentran en Génesis 4:2-25, abarcando su nacimiento (v. 2), su ofrenda aceptada (v. 4), su asesinato a manos de Caín (v. 8-9) y la nota de que Set fue dado ''en lugar de'' Hevel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92437, 'spa', 'Nombre propio', 'Hegai (también escrito Hegué) — nombre personal del eunuco del rey Asuero (Jerjes) que servía como guardián de las mujeres en el harén real de Susa. Es responsable del cuidado y la preparación de las jóvenes llevadas ante el rey, incluida Ester, quien gana su favor (Est 2:8–9, 15). El nombre aparece en formas variantes: הֵגֵא en Est 2:3 y הֵגַי/הֵגָי en 2:8, 15, y es probablemente un préstamo del persa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92438, 'spa', 'Meditar, reflexionar, murmurar sobre algo', 'Meditar, reflexionar, murmurar sobre algo: el sentido teológicamente más célebre, con 8 ocurrencias, centrado en la reflexión vocal sostenida sobre la ley, las obras o el carácter de Dios. Josué 1:8 ordena que la Torá ''no se aparte de tu boca; meditarás en ella de día y de noche''. Salmo 63:6 y 143:5 lo emplean para la reflexión nocturna sobre las obras de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92440, 'spa', 'Gemir, arrullar como paloma', 'Gemir, arrullar como paloma: 5 ocurrencias, todas en la literatura profética de Isaías y Jeremías, que expresan duelo comunal o personal. Isaías 38:14 compara el lamento de Ezequías con el gemido de una paloma; Isaías 59:11 empareja el gruñido del oso con el arrullo de la paloma como imágenes de la aflicción de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92444, 'spa', 'Pronunciar, hablar, declarar', 'Pronunciar, hablar, declarar: 6 ocurrencias donde la boca o la lengua es el sujeto explícito, desplazando el énfasis de la reflexión interna a la proclamación externa. ''Mi lengua proclamará tu justicia'' (Sal 35:28); ''la boca del justo profiere sabiduría'' (Sal 37:30). Los contextos sálmicos confirman una vocalización audible y pública.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92446, 'spa', 'Gruñir, rugir sobre la presa', 'Gruñir, rugir sobre la presa: una única ocurrencia vívida en Isaías 31:4, donde Yahvé es comparado con un león que ''ruge'' sobre su presa, sin dejarse intimidar por los pastores convocados contra él. Este es el uso más puramente onomatopéyico de hagah, despojado de contenido cognitivo y reducido a sonido crudo y amenazante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92447, 'spa', 'Murmurar, tramar, maquinar', 'Murmurar, tramar, maquinar: 5 ocurrencias donde el murmullo en voz baja toma un giro siniestro hacia la conspiración y la intriga. La instancia paradigmática es Salmo 2:1: ''¿Por qué se amotinan las naciones y los pueblos traman cosas vanas?'' Isaías 59:3,13 asocia este murmullo con la mentira y la opresión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92462, 'spa', 'Remoción enérgica', 'El verbo denota remoción contundente en los tres contextos: purgar impurezas (Pr 25:4), apartar a los malvados (Pr 25:5) y enviar al exilio o cribar (Is 27:8). La evidencia interlingüística apunta a una expulsión o separación activa, ya sea física, moral o judicial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92463, 'spa', 'Murmullo y lamento', 'El sustantivo abarca dominios acústicos y emocionales: el retumbar profundo del trueno (Job 37:2), el sonido fugaz de un suspiro humano que marca la brevedad de la vida (Sal 90:9) y las expresiones plañideras inscritas en un rollo profético (Ez 2:10). Las glosas interlingüísticas resaltan tanto la cualidad auditiva como el tono lastimero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92466, 'spa', 'Meditación y música', 'Música resonante, meditación, reflexión o maquinación — abarcando un arco semántico que va del sonido instrumental audible a la reflexión interior silenciosa y la conspiración hostil. En Sal 92:3 describe la música resonante de la lira (עֲלֵי הִגָּיוֹן בְּכִנּוֹר). En Sal 19:14 es la meditación del corazón (הֶגְיוֹן לִבִּי) ofrecida junto a las palabras como adoración. En Sal 9:16 aparece emparejado con Selah como aparente indicación litúrgica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92468, 'spa', 'Sierva egipcia de Sara que dio a luz a Ismael para Abraham', 'Sierva egipcia de Sara que dio a luz a Ismael para Abraham. Su narrativa abarca la huida y el encuentro divino junto al pozo de Beer-lajai-roi (Gn 16:1-14), la expulsión con Ismael (Gn 21:9-21) y la alegoría paulina del pacto del Sinaí (Gá 4:24-25). Las doce ocurrencias veterotestamentarias designan a esta única persona. El francés usa Agar, mientras que el español y el alemán conservan Hagar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92469, 'spa', 'Hagritas (grupo tribal)', 'Los hagritas como pueblo tribal (sustantivo plural), un grupo nómada al este de Galaad derrotado por las tribus transjordanas (1 Cr 5:10, 19-20) y listado entre los enemigos de Israel en Sal 83:6. Su asociación con grupos ismaelitas y arameos los ubica en las tierras fronterizas pastoriles entre el Israel sedentario y el desierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92471, 'spa', 'Hagrita (gentilicio)', 'Adjetivo gentilicio que designa a un individuo como perteneciente al pueblo hagrita. Se aplica a Jaziz el hagrita (1 Cr 27:31), supervisor de los rebaños de David. El nombramiento sugiere que la reputación de los hagritas como hábiles pastores era reconocida incluso por la corte israelita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92472, 'spa', 'Hagrí (nombre propio)', 'Nombre patronímico personal, Hagrí, que identifica al padre de Mibhar entre los valientes de David (1 Cr 11:38). El pasaje paralelo en 2 Sam 23:36 lee ''Baní el gadita'', lo que refleja incertidumbre textual sobre si se trata de un nombre propio o un gentilicio corrupto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92474, 'spa', 'Consejero real', 'Consejero, ministro (arameo) — alto funcionario asesor en la jerarquía cortesana babilónico-persa, procedente de un préstamo persa cuya forma original exacta es debatida. En Dan 3:24 Nabucodonosor convoca a sus consejeros tras ver cuatro figuras en el horno; en 3:27 verifican el milagro. Dan 4:36 registra a los consejeros buscando a Nabucodonosor al restablecerse su cordura. En Dan 6:7 conspiran contra Daniel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92475, 'spa', 'Nombre propio que designa a varias figuras edomitas', 'Nombre propio que designa a varias figuras edomitas: Hadad hijo de Bedad, rey de Edom que derrotó a Madián (Gn 36:35; 1 Cr 1:46); un rey edomita posterior (1 Cr 1:50-51); y sobre todo Hadad, el príncipe edomita que se convirtió en adversario de Salomón (1 R 11:14-22). El español, el francés y el alemán transliteran uniformemente como Hadad sin división semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92477, 'spa', 'Nombre propio del rey arameo de Soba, hijo de Rejob, cuyas fuerzas militares Dav', 'Nombre propio del rey arameo de Soba, hijo de Rejob, cuyas fuerzas militares David derrotó en las campañas registradas en 2 Samuel 8:3-12 y 10:16-19. Las glosas multilingues transliteran uniformemente el nombre (Hadadezer, Hadad-ezer, Hadadeser), y la forma de la LXX Ἁδρααζαρ conserva una variante textual. También mencionado en 1 Reyes 11:23 en relación con la huida previa de Rezón del servicio de Hadadezer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92485, 'spa', 'Nombre propio', 'Se emplea tanto para un epónimo tribal (Gn 10:27; 1 Cr 1:21) como para un diplomático individual (1 Cr 18:10). Los traductores retienen uniformemente el nombre propio, reconociendo su doble función en la genealogía y la narrativa histórica. La uniformidad interlingüística refleja la práctica convencional de no traducir nombres personales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92489, 'spa', 'Estrado, escabel', 'Estrado o escabel, siempre en la frase constructa ''estrado de [sus/tus] pies''. Teológicamente describe la tierra como reposapiés de Dios (Isa 66:1), el templo o arca como lugar donde reposa la presencia divina (Lam 2:1; 1 Cr 28:2; Sal 99:5; 132:7), y los enemigos conquistados puestos bajo los pies del rey mesiánico (Sal 110:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92495, 'spa', 'Mirto (planta)', 'El mirto o arrayán (Myrtus communis), planta perenne de hojas fragantes. Aparece en el paisaje visionario de Zacarías (Zac 1:8, 10, 11), en los dos retratos de restauración escatológica de Isaías donde reemplaza espinos y se une a otros árboles majestuosos (Isa 41:19; 55:13), y entre las ramas festivas reunidas para Sucot (Neh 8:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92499, 'spa', 'Empujar o arrojar físicamente a una persona con fuerza corporal', 'Empujar o arrojar físicamente a una persona con fuerza corporal. Sentido fundamental, destacado en la legislación sobre homicidio de Números 35:20-22, donde un empujón mortal determina la culpabilidad. Ezequiel 34:21 lo extiende al ganado que empuja con el hombro y el cuerno a los animales más débiles. En 2 Reyes 4:27, Guejazí empuja a la sunamita para apartarla de Eliseo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92502, 'spa', 'Expulsar o echar a un pueblo de su tierra, enfocándose en la remoción y el desti', 'Expulsar o echar a un pueblo de su tierra, enfocándose en la remoción y el destierro más que en el acto físico. En Deuteronomio 6:19 y 9:4, Dios expulsa a los enemigos de Israel delante de ellos. Josué 23:5 promete que Dios empujará y desposeerá a las naciones restantes. El español pasa de «empujar» a «expulsar», señalando el desplazamiento semántico del contacto corporal al desplazamiento territorial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92503, 'spa', 'Rechazar, despreciar o apartar en sentido figurado o relacional', 'Rechazar, despreciar o apartar en sentido figurado o relacional. Proverbios 10:3 declara que el SEÑOR «aparta» (yehdof) el antojo del malvado — no un empujón físico sino un repudio moral. La evidencia multilingüe confirma este giro: el español usa «rechaza», el hindi «thukrana» (despreciar), el coreano «mullichichida» (repeler). Una ocurrencia única pero teológicamente significativa que muestra la extensión completa del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92509, 'spa', 'Terreno escabroso', 'Elevarse o ser escabroso, referido al terreno: probablemente el sentido físico original de la raíz. En Is 45:2 el participio pasivo Qal הֲדוּרִים describe colinas escarpadas o ''lugares escabrosos'' que Dios allanará ante Ciro. La LXX lee ὄρη (''montañas''), confirmando la lectura topográfica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92510, 'spa', 'Honrar, ser majestuoso', 'Honrar, mostrar respeto o ser majestuoso: el sentido dominante, que abarca la deferencia hacia los ancianos (Lv 19:32), las advertencias de imparcialidad judicial (Éx 23:3; Lv 19:15) y la majestad divina (Is 63:1, ''majestuoso en su vestimenta''). Lm 5:12 lo extiende a la deshonra de los ancianos en el exilio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92512, 'spa', 'Glorificarse, jactarse', 'Glorificarse a sí mismo, jactarse: la forma reflexiva Hitpael en Pr 25:6, que advierte contra la autopromoción en presencia del rey. La estructura reflexiva (''te glorifiques'') distingue este sentido del honrar transitivo: aquí el sujeto infla su propio estatus en vez de elevar a otro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92516, 'spa', 'Glorificar a Dios', 'El verbo aparece tres veces en los capítulos arameos de Daniel, siempre dirigido hacia Dios. Nabucodonosor glorifica a Dios tras su humillación y restauración (Dn 4:34, 37); Belsasar es condenado por no hacerlo (Dn 5:23). Las glosas multilingües convergen en el campo semántico de honrar, glorificar y exaltar lo divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92517, 'spa', 'Majestad real', 'Describe la dignidad regia y el esplendor visible que Nabucodonosor perdió y recobró (Dn 4:30, 36) y que Dios le había concedido (Dn 5:18). Las glosas interlingüísticas (majestad, gloire) reflejan consistentemente el sentido honorífico de alto rango. No se trata de virtud interior, sino de la manifestación externa de la autoridad soberana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92520, 'spa', 'Esplendor, belleza', 'Esplendor, belleza: Magnificencia visual y belleza radiante -- el esplendor exterior de la creación de Dios, la apariencia de una persona o el adorno de una ciudad. El salmista declara que Dios está ''vestido de esplendor y majestad'' (Sal 104:1), y Levítico prescribe ''fruto de árboles hermosos'' para Sucot (Lev 23:40). La LXX traduce con horaios, apuntando a esta cualidad deslumbrante y visual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92524, 'spa', 'Majestad, dignidad', 'Majestad, dignidad: Grandeza imponente y presencia real o divina que inspira reverencia y exige respeto. Moisés bendice a José con la ''majestad de un toro primogénito'' (Dt 33:17), y el salmista alaba la voz de Dios como ''llena de majestad'' (Sal 29:4). En 1 Cr 16:27, majestad y fortaleza habitan en el santuario de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92526, 'spa', 'Honor, gloria', 'Honor, gloria: Honor atribuido, renombre o distinción reconocida que pertenece a una persona o es otorgada por Dios. Cuando Dios le dice a Job ''Adórnate de gloria y esplendor'' (Job 40:10), la palabra denota un honor que se viste como un manto. El salmista se maravilla de que Dios coronó al ser humano de ''gloria y honra'' (Sal 8:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92544, 'spa', 'Esplendor sagrado o real', 'Adorno, esplendor o gloria, especialmente la belleza majestuosa asociada al culto o a la dignidad real. El uso litúrgico predominante aparece en la frase הַדְרַת־קֹדֶשׁ, ''el esplendor de la santidad'', una convocatoria a la adoración (1 Cr 16:29; 2 Cr 20:21; Sal 29:2; 96:9). Proverbios 14:28 traslada el concepto a la esfera política: la muchedumbre es el esplendor del rey.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92547, 'spa', 'pronombre él/ella/ello', 'El pronombre personal estándar de tercera persona singular: él, ella o ello. Funciona como pronombre sujeto, pronombre reasuntivo y referencia anafórica general a lo largo de toda la Biblia hebrea. Con más de 1.400 apariciones desde Gn 4:20, es la forma no marcada para rastrear un participante discursivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92548, 'spa', 'demostrativo aquel/aquella', 'El uso demostrativo con el sentido de «aquel» o «aquel mismo», señalando un referente específico típicamente distante en el espacio, el tiempo o el discurso. Pasajes clave incluyen Gn 19:35 («aquella noche»), Gn 21:31 («aquel lugar») y Gn 26:24 («aquella noche»). Se distingue claramente del mero uso pronominal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92561, 'spa', 'copulativo esto es', 'Uso copulativo o identificador donde הוּא funciona como marcador predicativo que afirma identidad o equivalencia: «es», «esto es» o «el mismo es». Es el sentido más raro, con unas 13 apariciones. En Lv 10:3 Dios dice «esto es lo que habló el SEÑOR», y en Esd 7:8 la construcción identifica al propio Esdras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92576, 'spa', 'Él, ella, ello (pronombre personal)', 'Él, ella, ello (pronombre personal): El pronombre personal estándar de tercera persona singular en arameo -- él, ella o ello -- que cubre todas las funciones pronominales básicas: referencia al sujeto, identificación copulativa y reanudación enfática. Con 21 apariciones, abarca casi todos los usos. Dn 2:21 (''y él cambia los tiempos y las estaciones''), Dn 2:22 (''él revela las cosas profundas''), Esd 5:8 (''la obra se realiza con diligencia'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92584, 'spa', 'Aquel, aquella (demostrativo)', 'Aquel, aquella (demostrativo): Uso demostrativo que significa ''aquel/aquella'', señalando una entidad específica e identificada. La única aparición clara es Dn 2:32 -- הוּא צַלְמָא, ''aquella imagen'' -- donde Daniel identifica la gran estatua del sueño de Nabucodonosor. El pronombre aquí no simplemente retoma un sujeto mencionado antes, sino que apunta directamente al coloso visto en la visión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92586, 'spa', 'Ser o llegar a ser', 'Llegar a ser, ser, suceder: verbo hebreo poco común, cognado del arameo frecuente הֲוָא. Génesis 27:29 lo emplea en imperativo en la bendición de Isaac: ''sé señor de tus hermanos''. Isaías 16:4 utiliza el imperativo femenino en un ruego de asilo con posible colorido moabita. Eclesiastés recurre al participio (2:22) y al imperfecto (11:3) para reflexionar sobre lo que acontece.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92587, 'spa', 'Ser, existir', 'Ser, existir: el sentido copulativo y existencial básico, función principal a lo largo de Daniel y Esdras. Cubre enunciados de identidad, afirmaciones de existencia y predicación. El español ''será/estaba/estuve'', el francés ''être'' y el alemán ''sein'' lo traducen con su cópula estándar, confirmando su función estativa simple (Esd 4:12-13; 6:9; Dn 4:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92591, 'spa', 'Ser (auxiliar perifrástico)', 'Ser (auxiliar perifrástico): uso auxiliar con un participio siguiente para formar construcciones verbales perifrásticas que expresan acción continua, habitual o volitiva. En Dn 5:19, el verbo se combina con participios para producir ''a quien quería mataba / a quien quería dejaba con vida''. El español ''quería'' revela que la construcción transmite volición o hábito continuo, no mero estado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92606, 'spa', 'Llegar a ser, convertirse', 'Llegar a ser, convertirse: sentido transformativo que indica un cambio de estado, distinguido del simple ser. El árabe صَارَ (llegar a ser) en lugar de كَانَ (ser), el español ''se convirtió'' y el hindi ''हो गया'' (se volvió) confirman el cambio de significado. El pasaje clásico es Dn 2:35, donde la piedra ''se convirtió'' en un gran monte que llenó toda la tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92609, 'spa', 'Majestad, esplendor', 'Majestad, esplendor: El esplendor sobrecogedor o la majestad asociada con Dios o la realeza, frecuentemente emparejado con הָדָר en la poesía litúrgica y profética. Las traducciones en diversos idiomas convergen en ''majestad/esplendor''. Característico de la teofanía divina (Job 37:22) y la entronización real (1 Cr 29:25), este sentido capta la radiancia visible de la autoridad suprema.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92615, 'spa', 'Honor, dignidad', 'Honor, dignidad: Honor personal, dignidad o distinción que pertenece a un individuo o le es conferida, enfatizando la estima y el respeto más que la grandeza cósmica. En Nm 27:20 Moisés transfiere parte de su הוֹד a Josué como traspaso de autoridad; en Pr 5:9 advierte contra malgastar el propio vigor o reputación. Dn 11:21 lo usa para referirse a una dignidad real no legítimamente conferida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92631, 'spa', 'Nombre propio', 'Se emplea como nombre personal en tres listas genealógicas o censales (1 Cr 5:24; 9:7; Esd 2:40). Las glosas multilingües lo tratan como nombre propio, preservando la transliteración en lugar de intentar una traducción semántica. Cualquier conexión etimológica con la alabanza permanece como información de fondo, no activada en estos contextos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92633, 'spa', 'Nombre propio postexílico', 'הוֹדִיָּה (también Hodías) — nombre propio que significa ''mi esplendor es Yah,'' portado por varias figuras postexílicas. En 1 Cr 4:19 aparece en una genealogía de Judá. En Neh 10:10 y 10:13, levitas con este nombre sellan el pacto junto a Nehemías, y en Neh 10:18 un jefe del pueblo hace lo mismo. El elemento teofórico (-yah) lo vincula a la tradición litúrgica de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92635, 'spa', 'Destrucción, calamidad, ruina', 'Destrucción, calamidad, ruina envolvente: desastre que abruma y devora, a menudo como juicio divino contra los malvados o como aflicción del justo. Aparece 12 veces, principalmente en Salmos y Job, evocando un abismo de catástrofe. En Sal 5:9, los malvados están llenos de הַוּוֹת (''destrucciones''), y en Sal 52:2, la lengua trama הַוּוֹת como una navaja afilada. La calamidad de Job es tan pesada como la arena del mar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92639, 'spa', 'Deseo, codicia', 'Deseo maligno, codicia voraz: un apetito intenso que conduce a la ruina, típicamente atribuido a los malvados. En Pr 10:3, ''Jehová rechaza la הַוַּת de los malvados'', y en Pr 11:6, ''los traidores son atrapados por su propia הַוָּה''. Miq 7:3 habla del poderoso ''declarando el deseo (הַוַּת) de su alma''. Este sentido distingue el apetito interior de la catástrofe externa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92646, 'spa', 'Calamidad profética', 'Denota calamidad y desastre en oráculos proféticos de juicio. Describe la ruina que cae sobre Babilonia (Is 47:11) y oleadas sucesivas de desastre sobre Jerusalén (Ez 7:26). La evidencia multilingüe apunta uniformemente a una catástrofe repentina y abrumadora. La repetición en Ezequiel («desastre sobre desastre») enfatiza una devastación implacable y acumulativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92648, 'spa', '!Ay!', '!Ay!: exclamación de dolor, lamento o juicio profético que introduce declaraciones de desagrado divino o gritos de duelo. El español ''ay de'', el francés ''malheur'' y el alemán ''wehe'' convergen en ese tono doloroso y admonitorio. Se encuentra en todos los profetas, especialmente en los oráculos de ay de Isaías (Isa 1:4; 5:8) y en lamentos fúnebres (1 R 13:30; Jer 22:18). Las 50 ocurrencias lo establecen como el sentido abrumadoramente dominante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92651, 'spa', '!Ea! !Venid!', '!Ea! !Venid!: llamado de atención para convocar: ''!ea! !venid!'' Un uso positivo y excepcional de la interjección para invitar a los oyentes a acercarse. Solo aparece en Isa 55:1, donde Dios llama a los sedientos a venir y beber. El español ''Oh'' en lugar de ''Ay'' señala el cambio tonal del duelo a la invitación generosa, y el contexto de agua y vino gratuitos confirma la fuerza invitativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92652, 'spa', 'Ir, caminar', 'Ir, caminar (arameo) — movimiento físico de personas o cosas y, en sentido figurado, la manera de vivir o conducirse. En Esd 5:5 la obra ''prosigue'' sin impedimento; en 6:5 los utensilios del templo deben ''volver'' a Jerusalén; en 7:13 cualquier voluntario puede ''ir.'' Daniel emplea el participio Pael para Nabucodonosor ''paseando'' por su palacio (Dan 4:26) y el Hafel para los tres jóvenes caminando en el fuego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92653, 'spa', 'Locura moral', 'Locura como insensatez moral e intelectual — la temeridad irracional opuesta a la sabiduría. Las cuatro apariciones se hallan en Eclesiastés, donde el Predicador investiga lo que resulta vano (Ecl 1:17; 2:12; 7:25; 9:3). Emparejada con סִכְלוּת (''necedad'') y רַע (''mal''), el término no denota demencia clínica sino un rechazo voluntario de la recta razón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92655, 'spa', 'Tumulto y agitación', 'Estar en tumulto, murmurar, rugir o ser arrojado a la confusión, abarcando el alboroto colectivo, la agitación interior y la intervención divina que siembra pánico. Rut 1:19 registra una ciudad conmocionada; 1 Samuel 4:5 describe la tierra retumbando ante un clamor; 1 Reyes 1:45 pinta a Jerusalén bullendo de emoción; Salmo 55:2 expresa el gemido interior del salmista.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92658, 'spa', 'Riqueza, bienes', 'Riqueza, bienes: Riqueza material, bienes o posesiones acumuladas. El sentido dominante en Proverbios y Ezequiel, frecuentemente emparejado con עֹשֶׁר (Sal 112:3; Pr 8:18) o contrastado con la pobreza. Los oráculos de Ezequiel sobre Tiro lo usan para la mercancía comercial y la riqueza del comercio (Ez 27:12, 27, 33). Proverbios 10:15 y 18:11 describen la riqueza del hombre acaudalado como su ciudad fortificada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92661, 'spa', 'Suficiente, bastante', 'Suficiente, bastante: Uso adverbial o exclamativo que significa ''¡basta!'' Aparece únicamente en Proverbios 30:15-16, dentro del proverbio numérico sobre las cosas que nunca dicen ''basta'': el Seol, el vientre estéril, la tierra sedienta y el fuego. Este sentido se distingue tajantemente del significado de riqueza, y podría derivar de un sentido raigal más antiguo de ''sustancia/capacidad''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92671, 'spa', 'Oseas (hijo de Nun / rey de Israel) — Nombre propio usado para', 'Oseas (hijo de Nun / rey de Israel) — Nombre propio usado para: (a) el nombre original de Josué hijo de Nun antes de que Moisés lo renombrara Yehoshua (Núm 13:8, 16; Deut 32:44), (b) Oseas hijo de Ela, último rey del reino del norte de Israel que reinó durante la conquista asiria (2 Re 15:30; 17:1-6; 18:1, 9-10), (c) un jefe efrateo bajo David (1 Cr 27:20), y (d) un líder que selló el pacto bajo Nehemías (Neh 10:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92673, 'spa', 'Oseas (el profeta) — El profeta Oseas (hijo de Beeri), quien profetizó en el sig', 'Oseas (el profeta) — El profeta Oseas (hijo de Beeri), quien profetizó en el siglo VIII a.C. durante los reinados de Uzías hasta Ezequías de Judá y Jeroboam II de Israel. Las tres apariciones se encuentran en Oseas 1:1-2, la inscripción del libro y su mandato inicial. El nombre del profeta tiene una carga teológica profunda: Dios le ordena encarnar su amor redentor por el Israel infiel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92678, 'spa', 'Nombre propio', 'Aparece como nombre propio tanto en contextos narrativos (Jer 42:1; 43:2) como litúrgicos (Neh 12:32). Las traducciones multilingües transliteran el nombre de forma uniforme. Su significado teológico (''Yah ha salvado'') permanece implícito, evocando el patrón más amplio de esperanza salvífica en las prácticas de nomenclatura israelitas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92682, 'spa', 'Grito, clamor comunal', 'Grito o clamor comunal que abarca tanto el jubiloso grito de vendimia de los pisadores de uva como el amenazante grito de guerra del enemigo. En el sentido de vendimia, Isaías 16:9-10 lamenta el cese del heidád en los viñedos de Moab, y Jeremías 48:33 emplea un poderoso juego de palabras: ''heidád heidád lo heidád,'' el grito ya no es de vendimia sino del enemigo. En Jeremías 25:30, Yahvé ruge como pisadores de uva contra toda la tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92684, 'spa', 'ser, existir, haber', 'La columna vertebral copulativa y existencial de la narrativa hebrea: ''ser, fue, existir, había''. Abarca la función de enlace entre sujeto y predicado, la marcación de existencia y la fórmula וַיְהִי que abre cláusulas temporales. Con más de 3.500 apariciones, es el verbo más empleado de la sintaxis hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92736, 'spa', 'llegar a ser, convertirse', 'Sentido incoativo o transformador: ''llegar a ser, convertirse en, volverse'', indicando un cambio de estado y no mera existencia estática. La vara de Aarón ''se convirtió'' en serpiente (Éx 7:12), un río ''se hizo'' cuatro brazos (Gn 2:10), y Jacob confiesa ''he llegado a ser'' indigno (Gn 32:10). Se distingue del sentido 1 por implicar transición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92777, 'spa', 'Yo soy (autodeclaración divina)', 'La solemne autodeclaración divina אֶהְיֶה — ''Yo soy'' o ''Yo seré'' — concentrada en la teofanía de la zarza ardiente (Éx 3:14). La forma de primera persona del imperfecto porta fuerza tanto presente como futura, y los traductores de todas las tradiciones luchan por captar su plenitud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92778, 'spa', 'variante textual (ketiv)', 'Variantes ketiv/qeré de la tradición masorética donde el texto consonántico preserva una ortografía alternativa del verbo. No constituye un sentido semántico distinto, sino un fenómeno de crítica textual que aparece en descripciones de límites en Josué (15:4; 18:12, 14, 19; 19:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92794, 'spa', 'ha habido, ha sucedido', 'Matiz resultativo-perfectivo: ''ha habido, ha ocurrido'', enfatizando la naturaleza consumada o sin precedentes de un evento. Se usa para momentos singulares y trascendentales: ''no ha habido tal clamor'' en Egipto (Éx 11:6), ''¿se ha hecho esto?'' respecto a la coronación de Salomón (1 R 1:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92858, 'spa', 'Templo, edificio sagrado', 'Templo, edificio sagrado: el templo como lugar de culto, especialmente el Templo de YHWH en Jerusalén o la morada celestial de Dios. Abarca 68 de 80 ocurrencias, desde el tabernáculo en Silo donde el joven Samuel ministra (1 Sam 1:9; 3:3) hasta el clamor de David oído ''en su templo'' (2 Sam 22:7). El español ''el templo'', el francés ''le temple'' y el alemán ''der Tempel'' identifican unánimemente este sentido de edificio sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92865, 'spa', 'Palacio, residencia real', 'Palacio, residencia real: un palacio o residencia real, la morada arquitectónica grandiosa de un rey o gobernante, tanto de cortes israelitas como extranjeras. Aparece en el palacio de Acab junto a la viña de Nabot (1 R 21:1) y en la profecía de Isaías de que los hijos de Ezequías servirán en el palacio de Babilonia (2 R 20:18). El español pasa decididamente a ''palacio'' y el francés a ''palais''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92890, 'spa', 'Templo, santuario', 'Designa el edificio sagrado del templo, ya sea el santuario de Jerusalén o un recinto extranjero. Las memorias de Esdras usan la forma enfática para referirse a los vasos del templo llevados a Babilonia (Esd 5:14) y su restauración prevista (Esd 5:15; 6:5). Daniel 5:2-3 describe a Belsasar mandando traer los vasos de oro ''del templo'' en Jerusalén, confirmando la lectura sagrada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92893, 'spa', 'Palacio, residencia real', 'Se refiere al palacio del rey o residencia real como una gran estructura secular. Daniel lo emplea cuando Nabucodonosor camina por el techo ''del palacio real'' en Babilonia (Dn 4:29) y para sus aposentos personales (Dn 4:4, ''en mi palacio''). El español distingue ''del palacio'' y ''el palacio'' aquí, mientras la ambigüedad inherente de la palabra refleja la realidad del Antiguo Oriente Próximo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92900, 'spa', 'Hemán (músico/sabio levita) — Nombre propio הֵימָן (''fiel''), que se refiere prin', 'Hemán (músico/sabio levita) — Nombre propio הֵימָן (''fiel''), que se refiere principalmente al levita coatita designado como músico principal bajo David, jefe de uno de los tres gremios de adoración del templo junto a Asaf y Etán (1 Cr 15:17, 19; 25:1-6). También identificado como ''el ezraíta'' en el encabezado del Salmo 88 y mencionado entre los sabios cuya sabiduría Salomón superó (1 Re 4:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92904, 'spa', 'Hin (unidad de medida líquida)', 'Hin (unidad de medida líquida): Unidad de medida líquida equivalente a aproximadamente 6 litros (un sexto de bat), usada exclusivamente en contextos rituales y sacrificiales. Cantidades fraccionarias -- un cuarto de hin, un tercio de hin, medio hin -- especifican las cantidades precisas de aceite y vino para las ofrendas de cereal y las libaciones (Éx 29:40; Nm 15:4-10). Levítico 19:36 extiende el hin al ámbito de los pesos y medidas justas. La visión del templo de Ezequiel prescribe cantidades en hines para el sistema sacrificial reformado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92910, 'spa', 'Adelante, más allá — Adverbio que significa ''adelante, más lejos, más allá'', exp', 'Adelante, más allá — Adverbio que significa ''adelante, más lejos, más allá'', expresando extensión espacial o temporal desde un punto de referencia. Espacialmente indica dirección de alejamiento: ''¡apártate!'' (Gén 19:9), ''esparcid allá'' (Núm 16:37), ''más allá de Damasco'' (Amós 5:27), ''más allá de la torre del rebaño'' (Gén 35:21). Temporalmente establece umbrales abiertos: ''de ocho días en adelante'' para la elegibilidad sacrificial (Lev 22:27), ''de veinte años en adelante'' para el servicio levítico (Núm 8:24-25; 1 Cr 23:24, 27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92920, 'spa', 'Aquel (demostrativo distal)', 'Demostrativo distal: ''aquel, aquel de allá.'' Se usa para indicar un referente más lejano. En 1 Samuel 14:1, Jonatán propone cruzar a ''aquel lado'' (מֵעֵבֶר הַלָּז) de la guarnición filistea. En 2 Reyes 4:25, la mujer sunamita es identificada mientras se acerca desde la distancia. El español ''aquel/aquella'' confirma la deixis de lejanía, distinguiendo este sentido del proximal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92921, 'spa', 'Este (demostrativo proximal)', 'Demostrativo proximal: ''este, este de aquí.'' Se usa para indicar un referente cercano o inmediatamente presente. En Jueces 6:20, el ángel ordena a Gedeón colocar la ofrenda sobre ''esta roca'' (הַסֶּלַע הַלָּז). En 1 Samuel 17:26, David pregunta por ''este filisteo incircunciso.'' Los equivalentes en español ''este/esta'' confirman la fuerza deíctica de cercanía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92927, 'spa', 'Procesión, marcha sagrada', 'Procesión o marcha solemne, especialmente el avance teofánico de Dios hacia el santuario. Salmo 68:24 usa el plural dos veces: «Vieron tus procesiones, oh Dios, las procesiones de mi Dios, mi Rey, en el lugar santo». Nahúm 2:5 extiende el sentido a la marcha tambaleante de guerreros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92928, 'spa', 'Caravana, compañía viajera', 'Caravana o compañía de viajeros, un grupo que se desplaza junto. Job 6:19 empareja las caravanas de Tema con las compañías de Sabá, ambas buscando agua en el desierto. El árabe rukbān (''jinetes, caravana'') ofrece un paralelo semántico cognado para este sentido concreto y comercial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92930, 'spa', 'Caminos, conducta habitual', 'Caminos, costumbres o conducta en sentido abstracto. Proverbios 31:27 describe a la mujer virtuosa vigilando las halikhot de su hogar; Habacuc 3:6 habla de los caminos eternos de Dios. El vocablo pasa del movimiento físico al comportamiento habitual y la gobernanza divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (92933, 'spa', 'ir, viajar (Qal)', 'Movimiento físico básico en el Qal: ir, viajar, proseguir de un lugar a otro. El árabe ذهب y el español fue/partió lo traducen directamente. Cubre todas las conjugaciones Qal en contextos narrativos: Abraham viajando al sur (Gn 12:9), Labán partiendo (Gn 31:19), Balaam yendo a Balac (Nm 24:1).');